package cn.zj.zjmarket.infrastructure.adapter.repository;

import cn.zj.zjmarket.domain.refund.adapter.repository.IRefundRepository;
import cn.zj.zjmarket.domain.refund.model.Refund;
import cn.zj.zjmarket.domain.refund.model.Refund.*;
import cn.zj.zjmarket.domain.payment.model.valobj.ChannelFact;
import cn.zj.zjmarket.domain.payment.service.impl.PaymentService;
import cn.zj.zjmarket.infrastructure.gateway.codec.ContractCodec;
import com.fasterxml.jackson.databind.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.*;
import javax.sql.DataSource;
import java.util.*;

/** Marketplace only. Never touches channel tables or releases inventory. */
public final class RefundRepository implements IRefundRepository {
 private static final String NOW="CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED)";
 private final JdbcTemplate db;private final TransactionTemplate tx;private final Settings settings;private final ObjectMapper json=new ObjectMapper();private final String source,channel;
 public RefundRepository(DataSource ds,TransactionTemplate tx,Settings settings,String source,String channel){db=new JdbcTemplate(ds);this.tx=tx;this.settings=settings;this.source=source;this.channel=channel;}
 private RefundOutbox outbox;
 public void enableOutbox(RefundOutbox outbox){outbox.validateSchema();this.outbox=outbox;}
 private void materialize(String id){if(outbox!=null)outbox.materialize(id);}
 public List<String> releaseDue(int size){return db.queryForList("SELECT f.refund_id FROM b_refund f JOIN b_market_order o ON o.order_id=f.order_id LEFT JOIN b_trade_work w ON w.business_key=CONCAT(f.payment_id,':',f.order_id) AND w.kind='REFUND_OBLIGATION' WHERE f.funds_status='SUCCEEDED' AND f.eligibility_status='ELIGIBLE' AND f.release_status IN ('HELD','READY') AND (w.work_id IS NULL OR (w.state IN ('DEFERRED_B05','READY','WAITING_DEPENDENCY','LEASED') AND w.next_attempt_ms<="+NOW+" AND (w.lease_until_ms IS NULL OR w.lease_until_ms<="+NOW+"))) AND JSON_UNQUOTE(JSON_EXTRACT(o.a_evidence,'$.source'))=? AND JSON_UNQUOTE(JSON_EXTRACT(o.a_evidence,'$.channel'))=? ORDER BY w.next_attempt_ms,f.refund_id LIMIT ?",String.class,source,channel,size);}
 public boolean scoped(Map<String,Object> f){return count("SELECT COUNT(*) FROM b_market_order WHERE order_id=? AND JSON_UNQUOTE(JSON_EXTRACT(a_evidence,'$.source'))=? AND JSON_UNQUOTE(JSON_EXTRACT(a_evidence,'$.channel'))=?",f.get("order_id"),source,channel)==1;}
 public long syncRetryDelay(int failures){return settings.delay(failures);}
 public void withLocked(String id,Runnable action){tx.executeWithoutResult(s->{if(lock(id)!=null)action.run();});}
 public void backfillOutbox(int size){if(outbox==null)return;for(String id:db.queryForList("SELECT DISTINCT f.refund_id FROM b_refund f JOIN b_refund_attempt a ON a.refund_id=f.refund_id JOIN b_market_order o ON o.order_id=f.order_id WHERE COALESCE(f.sync_error,'')<>'LOCAL_REFUND_FACT_INVALID' AND JSON_UNQUOTE(JSON_EXTRACT(o.a_evidence,'$.source'))=? AND JSON_UNQUOTE(JSON_EXTRACT(o.a_evidence,'$.channel'))=? AND (NOT EXISTS(SELECT 1 FROM b_trade_outbox x WHERE x.refund_id=f.refund_id AND x.fact_version=a.pending_version) OR (a.result_version IS NOT NULL AND NOT EXISTS(SELECT 1 FROM b_trade_outbox x WHERE x.refund_id=f.refund_id AND x.fact_version=a.result_version))) ORDER BY f.refund_id LIMIT ?",String.class,source,channel,size))try{withLocked(id,()->materialize(id));}catch(IllegalArgumentException invalid){withLocked(id,()->{long n=now();db.update("UPDATE b_refund SET sync_status='REVIEW_REQUIRED',sync_error='LOCAL_REFUND_FACT_INVALID' WHERE refund_id=?",id);db.update("INSERT INTO b_trade_quarantine(quarantine_id,receipt_key,topic,tag,body,body_hash,reason,created_at_ms) SELECT ?,refund_id,'LOCAL','REFUND_FACT',snapshot,snapshot_hash,'LOCAL_REFUND_FACT_INVALID',? FROM b_refund WHERE refund_id=? ON DUPLICATE KEY UPDATE quarantine_id=quarantine_id",UUID.randomUUID().toString(),n,id);});}}
 public void validateSchema(){db.queryForList("SELECT check_only,check_previous_due_ms FROM b_refund_task LIMIT 0");Refund.require(db.queryForObject("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('b_refund_attempt','b_refund_task','b_sim_refund','b_sim_refund_attempt','b_sim_refund_notification')",Long.class)==5);db.queryForList("SELECT fact_version,current_attempt_id,success_hash FROM b_refund LIMIT 0");}
 private String digest(byte[] raw){try{return ContractCodec.sha256(raw);}catch(Exception e){throw new IllegalArgumentException(e);}}
 private long now(){return db.queryForObject("SELECT "+NOW,Long.class);}
 private Map<String,Object> first(String sql,Object...args){var rows=db.queryForList(sql,args);return rows.isEmpty()?null:rows.getFirst();}
 private long count(String sql,Object...args){return db.queryForObject(sql,Long.class,args);}
 private byte[] bytes(Object value){try{return new ContractCodec().encode(value);}catch(Exception e){throw new IllegalArgumentException("Refund encoding failed",e);}}
 private JsonNode evidence(Map<String,Object> row,String field){byte[] raw=(byte[])row.get(field);Refund.require(raw!=null&&digest(raw).equals(row.get(field.equals("result_fact")?"result_hash":field+"_hash")));try{return json.readTree(raw);}catch(Exception e){throw new IllegalArgumentException("Refund stored evidence invalid",e);}}
 private Request request(Map<String,Object> attempt){try{var req=json.readValue((byte[])attempt.get("request"),Request.class);Refund.require(req.hash().equals(attempt.get("request_hash")));return req;}catch(Exception e){throw new IllegalArgumentException("Refund request invalid",e);}}
 private Map<String,Object> lock(String id){var before=first("SELECT order_id FROM b_refund WHERE refund_id=?",id);if(before==null)return null;String order=before.get("order_id").toString();var o=first("SELECT user_id,goods_id FROM b_market_order WHERE order_id=?",order);Refund.require(o!=null);String u=o.get("user_id").toString(),g=o.get("goods_id").toString();
  db.queryForList("SELECT user_id FROM b_user WHERE user_id=? FOR UPDATE",u);db.queryForList("SELECT goods_id FROM b_product WHERE goods_id=? FOR UPDATE",g);db.queryForList("SELECT user_id FROM b_purchase_guard WHERE user_id=? AND goods_id=? FOR UPDATE",u,g);db.queryForList("SELECT goods_id FROM b_inventory_account WHERE goods_id=? FOR UPDATE",g);db.queryForList("SELECT order_id FROM b_market_order WHERE order_id=? FOR UPDATE",order);db.queryForList("SELECT order_id FROM b_inventory_reservation WHERE order_id=? FOR UPDATE",order);db.queryForList("SELECT order_id FROM b_trade_coordination WHERE order_id=? FOR UPDATE",order);db.queryForList("SELECT payment_id FROM b_payment WHERE order_id=? FOR UPDATE",order);db.queryForList("SELECT a.attempt_id FROM b_payment_attempt a JOIN b_payment p ON p.payment_id=a.payment_id WHERE p.order_id=? ORDER BY a.attempt_no FOR UPDATE",order);db.queryForList("SELECT operation_id FROM b_payment_operation WHERE order_id=? ORDER BY operation_id FOR UPDATE",order);db.queryForList("SELECT operation_id FROM b_order_operation WHERE order_id=? ORDER BY operation_id FOR UPDATE",order);db.queryForList("SELECT t.payment_id FROM b_payment_task t JOIN b_payment p ON p.payment_id=t.payment_id WHERE p.order_id=? FOR UPDATE",order);db.queryForList("SELECT owner_id FROM b_order_block WHERE order_id=? ORDER BY kind,owner_id FOR UPDATE",order);var f=first("SELECT * FROM b_refund WHERE refund_id=? FOR UPDATE",id);db.queryForList("SELECT attempt_id FROM b_refund_attempt WHERE refund_id=? ORDER BY attempt_no FOR UPDATE",id);db.queryForList("SELECT refund_id FROM b_refund_task WHERE refund_id=? FOR UPDATE",id);if(outbox!=null)db.queryForList("SELECT event_id FROM b_trade_outbox WHERE payment_id=? ORDER BY event_id FOR UPDATE",f.get("payment_id"));return f;
 }
 Map<String,Object> cursor(Map<String,Object> f){return first("SELECT * FROM b_team_cursor WHERE source=? AND channel=? AND team_id=? FOR UPDATE",source,channel,f.get("team_id"));}
 void eligible(Map<String,Object> f,Map<String,Object> cursor){
  Refund.require("ELIGIBLE".equals(f.get("eligibility_status")));String oid=f.get("order_id").toString();var o=first("SELECT * FROM b_market_order WHERE order_id=?",oid);var p=first("SELECT * FROM b_payment WHERE payment_id=?",f.get("payment_id"));Refund.require(o!=null&&p!=null&&oid.equals(p.get("order_id"))&&f.get("user_id").equals(p.get("user_id"))&&"SUCCEEDED".equals(p.get("funds_state"))&&f.get("amount").equals(p.get("amount"))&&"CNY".equals(p.get("currency")));
  JsonNode snapshot=evidence(f,"snapshot"),proof=evidence(f,"eligibility_proof");Refund.require(snapshot.path("orderId").asText().equals(oid)&&snapshot.path("paymentId").asText().equals(p.get("payment_id"))&&snapshot.path("successHash").asText().equals(p.get("success_hash"))&&proof.path("refundSnapshotHash").asText().equals(f.get("snapshot_hash")));
  byte[] paid=(byte[])p.get("success_fact");Refund.require(paid!=null&&digest(paid).equals(p.get("success_hash")));try{Refund.require(snapshot.path("successFact").asText().equals(new String(paid,java.nio.charset.StandardCharsets.UTF_8)));var fact=json.readValue(paid,ChannelFact.class);Refund.require(fact.channel().paymentId().equals(p.get("payment_id"))&&fact.channel().attemptId().equals(p.get("success_attempt_id"))&&fact.channel().amount().equals(f.get("amount").toString())&&fact.channel().paidAt()==((Number)p.get("paid_at_ms")).longValue()&&fact.snapshotHash().equals(p.get("snapshot_hash"))&&"PAID".equals(fact.gate())&&"SUCCEEDED".equals(fact.channel().state()));}catch(java.io.IOException e){throw new IllegalArgumentException(e);}
  JsonNode orderEvidence;try{orderEvidence=json.readTree(o.get("a_evidence").toString());}catch(Exception e){throw new IllegalArgumentException(e);}Refund.require(source.equals(orderEvidence.path("source").asText())&&channel.equals(orderEvidence.path("channel").asText())&&f.get("team_id").equals(orderEvidence.path("teamId").asText()));
  var team=proof.path("team");Refund.require("FAILED".equals(team.path("status").asText())&&f.get("team_id").equals(team.path("teamId").asText()));long teamVersion=cn.zj.zjmarket.domain.order.model.valobj.ReservationEvidence.version(team.path("version").asText());
  if(cursor!=null)Refund.require(!Boolean.TRUE.equals(cursor.get("review_required"))&&!"TEAM_COMPLETED".equals(cursor.get("status"))&&((Number)cursor.get("team_version")).longValue()<=teamVersion);
  Refund.require(!"GROUP_COMPLETED".equals(o.get("business_status"))&&count("SELECT COUNT(*) FROM b_fulfillment WHERE order_id=?",oid)==0&&count("SELECT COUNT(*) FROM b_inventory_reservation WHERE order_id=? AND state='CONFIRMED'",oid)==0);
  Refund.require(count("SELECT COUNT(*) FROM b_order_block WHERE order_id=? AND state='ACTIVE' AND (kind<>'RECONCILIATION' OR owner_id<>?)",oid,f.get("team_id"))==0);
  Set<String> reasons=Set.of("TEAM_FAILED","TEAM_RECONCILIATION_REQUIRED","PAYMENT_OUTSIDE_WINDOW");if(Boolean.TRUE.equals(o.get("review_required")))Refund.require(reasons.contains(Objects.toString(o.get("last_error"),"")));if(Boolean.TRUE.equals(p.get("review_required")))Refund.require(reasons.contains(Objects.toString(p.get("last_error"),"")));
  var member=first("SELECT m.*,t.task_id AS original_task FROM b_reconciliation_member m JOIN b_reconciliation_task t ON t.task_id=m.task_id WHERE m.out_trade_no=? AND t.team_id=? AND t.source=? AND t.channel=?",oid,f.get("team_id"),source,channel);Refund.require(member!=null&&Boolean.TRUE.equals(member.get("finalized"))&&Objects.equals(proof.path("member").asText(),member.get("proof_hash")==null?member.get("frozen_hash"):member.get("proof_hash")));
  String basis=Objects.toString(f.get("eligibility_basis"),"");if(basis.equals("OUTSIDE_WINDOW_RESOLVED")){var sub=first("SELECT * FROM b_reconciliation_submission WHERE task_id=?",member.get("task_id"));Refund.require(sub!=null&&"ACKNOWLEDGED".equals(sub.get("state"))&&proof.path("submissionHash").asText().equals(sub.get("request_hash"))&&"FAILED".equals(evidence(sub,"response").path("teamStatus").asText()));Refund.require("PAID_OUTSIDE_WINDOW".equals(member.get("state"))&&evidence(member,"decision").path("refundId").asText().equals(f.get("refund_id")));}
  else{Refund.require(basis.equals("TEAM_FAILED_ACCEPTED"));JsonNode paidMember=evidence(member,"frozen").path("payment");boolean accepted=paidMember.path("paymentId").asText().equals(p.get("payment_id"))&&paidMember.path("paidAmount").asText().equals(f.get("amount").toString())&&paidMember.path("paidAt").asText().equals(PaymentService.time(((Number)p.get("paid_at_ms")).longValue()));Refund.require(accepted||"PAID_ACCEPTED".equals(member.get("state"))&&"ACCEPTED".equals(p.get("a_acceptance")));}
 }
 private boolean current(Map<String,Object> task,Lease lease){long n=now();return task!=null&&"LEASED".equals(task.get("state"))&&lease.token().equals(task.get("lease_token"))&&lease.intentVersion()==((Number)task.get("intent_version")).longValue()&&task.get("lease_until_ms")!=null&&((Number)task.get("lease_until_ms")).longValue()>n;}
 public void discover(int size){for(String id:db.queryForList("SELECT f.refund_id FROM b_refund f JOIN b_market_order o ON o.order_id=f.order_id WHERE f.eligibility_status='ELIGIBLE' AND f.funds_status<>'SUCCEEDED' AND JSON_UNQUOTE(JSON_EXTRACT(o.a_evidence,'$.source'))=? AND JSON_UNQUOTE(JSON_EXTRACT(o.a_evidence,'$.channel'))=? AND NOT EXISTS(SELECT 1 FROM b_refund_task t WHERE t.refund_id=f.refund_id) ORDER BY f.created_at_ms,f.refund_id LIMIT ?",String.class,source,channel,size))admit(id);}
 public void admit(String id){tx.executeWithoutResult(s->{var f=lock(id);if(f==null||!"ELIGIBLE".equals(f.get("eligibility_status"))||"SUCCEEDED".equals(f.get("funds_status")))return;Refund.require(count("SELECT COUNT(*) FROM b_market_order WHERE order_id=? AND JSON_UNQUOTE(JSON_EXTRACT(a_evidence,'$.source'))=? AND JSON_UNQUOTE(JSON_EXTRACT(a_evidence,'$.channel'))=?",f.get("order_id"),source,channel)==1);long n=now();db.update("INSERT INTO b_refund_task(refund_id,next_attempt_ms,created_at_ms,updated_at_ms) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE refund_id=refund_id",id,n,n,n);});}
 public List<String> due(int size){return db.queryForList("SELECT t.refund_id FROM b_refund_task t JOIN b_refund f ON f.refund_id=t.refund_id JOIN b_market_order o ON o.order_id=f.order_id WHERE t.state IN ('READY','LEASED','WAITING_DEPENDENCY') AND t.next_attempt_ms<="+NOW+" AND (t.lease_until_ms IS NULL OR t.lease_until_ms<="+NOW+") AND JSON_UNQUOTE(JSON_EXTRACT(o.a_evidence,'$.source'))=? AND JSON_UNQUOTE(JSON_EXTRACT(o.a_evidence,'$.channel'))=? ORDER BY t.next_attempt_ms,t.refund_id LIMIT ?",String.class,source,channel,size);}
 public void lockQualification(Map<String,Object> f){cursor(f);for(String id:db.queryForList("SELECT task_id FROM b_reconciliation_task WHERE source=? AND channel=? AND team_id=? ORDER BY task_id FOR UPDATE",String.class,source,channel,f.get("team_id"))){db.queryForList("SELECT out_trade_no FROM b_reconciliation_member WHERE task_id=? ORDER BY out_trade_no FOR UPDATE",id);db.queryForList("SELECT completion_id FROM b_reconciliation_submission WHERE task_id=? FOR UPDATE",id);}}
 public Lease claim(String id){return tx.execute(s->{var f=lock(id);if(f==null||!scoped(f))return null;var task=first("SELECT * FROM b_refund_task WHERE refund_id=?",id);var c=cursor(f);long n=now();if(task==null||!Set.of("READY","LEASED","WAITING_DEPENDENCY").contains(task.get("state"))||((Number)task.get("next_attempt_ms")).longValue()>n||task.get("lease_until_ms")!=null&&((Number)task.get("lease_until_ms")).longValue()>n)return null;
  if(Boolean.TRUE.equals(task.get("check_only"))){if(f.get("current_attempt_id")==null){restoreCheck(id,n);return null;}var a=first("SELECT * FROM b_refund_attempt WHERE attempt_id=?",f.get("current_attempt_id"));String token=UUID.randomUUID().toString();db.update("UPDATE b_refund_task SET state='LEASED',lease_token=?,lease_until_ms=?,updated_at_ms=? WHERE refund_id=?",token,n+settings.leaseMillis(),n,id);return new Lease(request(a),token,((Number)task.get("intent_version")).longValue(),true);}
  try{eligible(f,c);}catch(IllegalArgumentException conflict){quarantine(id,"ELIGIBILITY_CONFLICT",n);return null;}if("SUCCEEDED".equals(f.get("funds_status"))){db.update("UPDATE b_refund_task SET state='DONE',lease_token=NULL,lease_until_ms=NULL WHERE refund_id=?",id);return null;}
  Map<String,Object> a=f.get("current_attempt_id")==null?null:first("SELECT * FROM b_refund_attempt WHERE attempt_id=?",f.get("current_attempt_id"));
  if(a==null||"FAILED".equals(a.get("state"))){int number=a==null?1:Math.addExact(((Number)a.get("attempt_no")).intValue(),1);long version=Math.addExact(((Number)f.get("fact_version")).longValue(),1);var p=first("SELECT * FROM b_payment WHERE payment_id=?",f.get("payment_id"));ChannelFact paid;try{paid=json.readValue((byte[])p.get("success_fact"),ChannelFact.class);}catch(Exception e){throw new IllegalArgumentException(e);}var req=new Request(id,f.get("order_id").toString(),f.get("payment_id").toString(),p.get("success_attempt_id").toString(),paid.channel().channelTransactionId(),((Number)p.get("paid_at_ms")).longValue(),p.get("snapshot_hash").toString(),p.get("success_hash").toString(),f.get("amount").toString(),"CNY",UUID.randomUUID().toString(),number);byte[] pending=versionFact(req,"PENDING",version,n,null);db.update("INSERT INTO b_refund_attempt(attempt_id,refund_id,attempt_no,request,request_hash,pending_version,pending_fact,pending_hash,created_at_ms,updated_at_ms) VALUES(?,?,?,?,?,?,?,?,?,?)",req.attemptId(),id,number,bytes(req),req.hash(),version,pending,digest(pending),n,n);db.update("UPDATE b_refund SET current_attempt_id=?,funds_status='PENDING',fact_version=?,version=version+1,updated_at_ms=? WHERE refund_id=?",req.attemptId(),version,n,id);a=first("SELECT * FROM b_refund_attempt WHERE attempt_id=?",req.attemptId());}
  materialize(id);Request req=request(a);String token=UUID.randomUUID().toString();db.update("UPDATE b_refund_attempt SET possible_sent=TRUE,updated_at_ms=? WHERE attempt_id=?",n,req.attemptId());db.update("UPDATE b_refund_task SET state='LEASED',lease_token=?,lease_until_ms=?,updated_at_ms=? WHERE refund_id=?",token,n+settings.leaseMillis(),n,id);return new Lease(req,token,((Number)task.get("intent_version")).longValue());});}
 private void restoreCheck(String id,long n){db.update("UPDATE b_refund_task SET state=COALESCE(check_previous_state,'WAITING_DEPENDENCY'),next_attempt_ms=COALESCE(check_previous_due_ms,next_attempt_ms),check_only=FALSE,check_previous_state=NULL,check_previous_due_ms=NULL,lease_token=NULL,lease_until_ms=NULL,updated_at_ms=? WHERE refund_id=?",n,id);}
 public void finishCheck(Lease l,Fact fact){tx.executeWithoutResult(s->{var f=lock(l.request().refundId());if(f==null)return;var t=first("SELECT * FROM b_refund_task WHERE refund_id=?",l.request().refundId());if(!current(t,l)||!Boolean.TRUE.equals(t.get("check_only")))return;long n=now();if(fact==null||"UNKNOWN".equals(fact.status())){if(fact!=null)fact.validate(l.request(),n);release(t,l.request().refundId(),"WAITING_DEPENDENCY","CHECK_PENDING",false,n);return;}
  fact.validate(l.request(),n);var a=first("SELECT * FROM b_refund_attempt WHERE attempt_id=?",l.request().attemptId());if(a.get("result_fact")!=null){if(applied(fact))restoreCheck(l.request().refundId(),n);else{quarantine(l.request().refundId(),"CHECK_FACT_CONFLICT",n);db.update("UPDATE b_refund_task SET check_only=FALSE,check_previous_state=NULL,check_previous_due_ms=NULL WHERE refund_id=?",l.request().refundId());}return;}
  finish(l,fact);db.update("UPDATE b_refund_task SET check_only=FALSE,check_previous_state=NULL,check_previous_due_ms=NULL WHERE refund_id=?",l.request().refundId());});}
 private byte[] versionFact(Request req,String state,long version,long occurred,Fact channelFact){var result=new LinkedHashMap<String,Object>();result.put("refundId",req.refundId());result.put("paymentId",req.paymentId());result.put("outTradeNo",req.orderId());result.put("refundAmount",req.amount());result.put("currency",req.currency());result.put("refundStatus",state);result.put("refundVersion",Long.toString(version));result.put("occurredAt",PaymentService.time(occurred));result.put("paidAt",PaymentService.time(req.paidAt()));result.put("paidAmount",req.amount());if(channelFact!=null)result.put("channelFact",channelFact);return bytes(result);}
 public boolean authorize(Lease l){return Boolean.TRUE.equals(tx.execute(s->{var f=lock(l.request().refundId());if(f==null)return false;var task=first("SELECT * FROM b_refund_task WHERE refund_id=?",l.request().refundId());var c=cursor(f);if(!current(task,l))return false;Refund.require(l.request().attemptId().equals(f.get("current_attempt_id"))&&request(first("SELECT * FROM b_refund_attempt WHERE attempt_id=?",l.request().attemptId())).equals(l.request()));try{eligible(f,c);return true;}catch(IllegalArgumentException conflict){quarantine(l.request().refundId(),"ELIGIBILITY_CONFLICT_BEFORE_CALL",now());return false;}}));}
 public boolean renew(Lease l){return Boolean.TRUE.equals(tx.execute(s->{var task=first("SELECT * FROM b_refund_task WHERE refund_id=? FOR UPDATE",l.request().refundId());if(!current(task,l))return false;long n=now();db.update("UPDATE b_refund_task SET lease_until_ms=?,updated_at_ms=? WHERE refund_id=?",n+settings.leaseMillis(),n,l.request().refundId());return true;}));}
 public void finish(Lease l,Fact fact){tx.executeWithoutResult(s->{var f=lock(l.request().refundId());if(f==null)return;var task=first("SELECT * FROM b_refund_task WHERE refund_id=?",l.request().refundId());var c=cursor(f);if(!current(task,l))return;Refund.require(l.request().attemptId().equals(f.get("current_attempt_id"))&&request(first("SELECT * FROM b_refund_attempt WHERE attempt_id=?",l.request().attemptId())).equals(l.request()));long n=now();fact.validate(l.request(),n);boolean valid=true;try{eligible(f,c);}catch(IllegalArgumentException conflict){valid=false;}
  if(fact.status().equals("UNKNOWN")){db.update("UPDATE b_refund SET funds_status='UNKNOWN',version=version+1,updated_at_ms=? WHERE refund_id=?",n,l.request().refundId());db.update("UPDATE b_refund_attempt SET state='UNKNOWN',updated_at_ms=? WHERE attempt_id=?",n,l.request().attemptId());if(!valid)quarantine(l.request().refundId(),"ELIGIBILITY_CONFLICT",n);else release(task,l.request().refundId(),"WAITING_DEPENDENCY","CHANNEL_UNKNOWN",false,n);return;}
  long version=Math.addExact(((Number)f.get("fact_version")).longValue(),1);byte[] result=versionFact(l.request(),fact.status(),version,n,fact);db.update("UPDATE b_refund_attempt SET state=?,result_version=?,result_fact=?,result_hash=?,updated_at_ms=? WHERE attempt_id=? AND state IN ('PENDING','UNKNOWN')",fact.status(),version,result,digest(result),n,l.request().attemptId());
  byte[] raw=bytes(fact);boolean success=fact.status().equals("SUCCEEDED");db.update("UPDATE b_refund SET funds_status=?,fact_version=?,success_fact=?,success_hash=?,refunded_at_ms=?,version=version+1,updated_at_ms=? WHERE refund_id=?",fact.status(),version,success?raw:null,success?digest(raw):null,success?fact.refundedAt():null,n,l.request().refundId());
  materialize(l.request().refundId());if(!valid)quarantine(l.request().refundId(),"ELIGIBILITY_CONFLICT_AFTER_CHANNEL",n);else if(success)db.update("UPDATE b_refund_task SET state='DONE',failure_count=0,last_error=NULL,lease_token=NULL,lease_until_ms=NULL,updated_at_ms=? WHERE refund_id=?",n,l.request().refundId());else release(task,l.request().refundId(),"READY","CHANNEL_FAILED",true,n);
 });}
 private void quarantine(String id,String reason,long n){db.update("UPDATE b_refund SET eligibility_status='REVIEW_REQUIRED',version=version+1,updated_at_ms=? WHERE refund_id=?",n,id);db.update("UPDATE b_refund_task SET state='REVIEW_REQUIRED',intent_version=intent_version+1,last_error=?,check_only=FALSE,check_previous_state=NULL,check_previous_due_ms=NULL,lease_token=NULL,lease_until_ms=NULL,updated_at_ms=? WHERE refund_id=?",reason,n,id);}
 private void release(Map<String,Object> task,String id,String state,String error,boolean business,long n){int failures=business?((Number)task.get("business_failures")).intValue()+1:((Number)task.get("failure_count")).intValue()+1;db.update("UPDATE b_refund_task SET state=?,next_attempt_ms=?,failure_count=?,business_failures=?,alerted=alerted OR ?>=5,last_error=?,lease_token=NULL,lease_until_ms=NULL,updated_at_ms=? WHERE refund_id=?",state,n+settings.delay(failures),business?0:failures,business?failures:((Number)task.get("business_failures")).intValue(),failures,error,n,id);if(failures==5)TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){public void afterCommit(){System.getLogger(RefundRepository.class.getName()).log(System.Logger.Level.WARNING,"Refund recovery requires attention; refundId="+id+", automaticRecovery=continuing");}});}
 public void defer(Lease l,boolean conflict){tx.executeWithoutResult(s->{var f=lock(l.request().refundId());if(f==null)return;var task=first("SELECT * FROM b_refund_task WHERE refund_id=?",l.request().refundId());if(!current(task,l))return;long n=now();if(conflict){quarantine(l.request().refundId(),"CHANNEL_FACT_CONFLICT",n);return;}db.update("UPDATE b_refund SET funds_status='UNKNOWN',version=version+1,updated_at_ms=? WHERE refund_id=? AND funds_status<>'SUCCEEDED'",n,l.request().refundId());db.update("UPDATE b_refund_attempt SET state='UNKNOWN',updated_at_ms=? WHERE attempt_id=? AND state='PENDING'",n,l.request().attemptId());release(task,l.request().refundId(),"WAITING_DEPENDENCY","CHANNEL_UNAVAILABLE",false,n);});}
 public Request noticeRequest(Notice notice){var a=first("SELECT * FROM b_refund_attempt WHERE refund_id=? AND attempt_id=?",notice.refundId(),notice.attemptId());return a==null?null:request(a);}
 public void quarantineNotice(Notice notice){tx.executeWithoutResult(s->{var f=lock(notice.refundId());if(f==null)return;Refund.require(first("SELECT attempt_id FROM b_refund_attempt WHERE refund_id=? AND attempt_id=?",notice.refundId(),notice.attemptId())!=null);quarantine(notice.refundId(),"NOTICE_FACT_CONFLICT",now());});}
 public boolean applied(Fact fact){if(fact==null)return false;var a=first("SELECT * FROM b_refund_attempt WHERE refund_id=? AND attempt_id=?",fact.request().refundId(),fact.request().attemptId());if(a==null||a.get("result_fact")==null)return false;Refund.require(request(a).equals(fact.request()));var frozen=evidence(a,"result_fact");try{Refund.require(fact.equals(json.treeToValue(frozen.path("channelFact"),Fact.class)));return true;}catch(java.io.IOException e){throw new IllegalArgumentException(e);}}
}
